typedef NetworkProbe = Future<bool> Function();
class WelcomeCard extends StatefulWidget { final Map<String,dynamic> sesi; final NetworkProbe? networkProbe; const WelcomeCard({super.key,required this.sesi,this.networkProbe}); @override State<WelcomeCard> createState()=>_WelcomeCardState(); }
class _WelcomeCardState extends State<WelcomeCard> with WidgetsBindingObserver { bool? _online; bool _checking=false,_loadingSummary=false; int _total=0,_waiting=0,_progress=0,_done=0; NetworkProbe get _probe=>widget.networkProbe??NetworkStatusService.isOnline; String get _identity=>'${widget.sesi['subTim']??widget.sesi['tim']??''} ${widget.sesi['username']??''}'.toLowerCase(); bool get _showNonHarSummary=>HarExecution.allowedTypes(widget.sesi).isEmpty; bool get _isInsdu=>_identity.contains('inspeksi gardu')||_identity.contains('insdu'); bool get _isRow=>!_isInsdu&&_identity.contains('row');
