@override void dispose(){WidgetsBinding.instance.removeObserver(this);super.dispose();} String _dateText(){final now=DateTime.now();const days=['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'],months=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];return '${days[now.weekday-1]}, ${now.day} ${months[now.month-1]} ${now.year}';}
@override Widget build(BuildContext context){final subTim=(widget.sesi['subTim']??widget.sesi['tim']??'-').toString(),ulp=(widget.sesi['ulp']??'-').toString(),bidang=(widget.sesi['bidang']??widget.sesi['Bidang']??'-').toString();return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[_welcomeCard(subTim:subTim,ulp:ulp,bidang:bidang),if(_showNonHarSummary)...[const SizedBox(height:16),if(_loadingSummary&&_total==0)const LinearProgressIndicator()else if(_isRow)WoSummaryCard.row(total:_total,penugasan:_waiting,progress:_progress,selesai:_done)else WoSummaryCard.insjar(total:_total,menunggu:_waiting,sedang:_progress,selesai:_done)]]);}
